package com.jarvis.fa;
import android.app.*;import android.content.*;import android.os.*;
public class ReminderReceiver extends BroadcastReceiver{
 @Override public void onReceive(Context c,Intent i){String title=i.getStringExtra("title");if(title==null)title="یادآوری جارویس";int id=i.getIntExtra("id",0);NotificationManager nm=(NotificationManager)c.getSystemService(Context.NOTIFICATION_SERVICE);if(Build.VERSION.SDK_INT>=26){NotificationChannel ch=new NotificationChannel("jarvis_reminders","یادآوری‌های جارویس",NotificationManager.IMPORTANCE_HIGH);nm.createNotificationChannel(ch);}Intent open=new Intent(c,MainActivity.class).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK|Intent.FLAG_ACTIVITY_CLEAR_TOP);PendingIntent content=PendingIntent.getActivity(c,id,open,PendingIntent.FLAG_UPDATE_CURRENT|PendingIntent.FLAG_IMMUTABLE);Notification.Builder b=Build.VERSION.SDK_INT>=26?new Notification.Builder(c,"jarvis_reminders"):new Notification.Builder(c);b.setContentTitle("JARVIS • REMINDER").setContentText(title).setSmallIcon(android.R.drawable.ic_dialog_info).setContentIntent(content).setAutoCancel(true);nm.notify(id==0?(int)(System.currentTimeMillis()%100000):id,b.build());if(id!=0)new ReminderEngine(c).markFired(id);}
}
